#include <stdio.h>
#include <string.h>
void buildNext(const char *p,int m,int next[]){
    next[1]=0;
    for(int j=1,k=0;j<m;){
        if(k==0 || p[j-1]==p[k-1]){ j++; k++; next[j]=k; }
        else k=next[k];
    }
}
int main(void){
    const char *t="ababcabcacbab", *p="abcac";
    int n=(int)strlen(t), m=(int)strlen(p), next[64];
    buildNext(p,m,next);
    printf("文本: %s\n模式: %s\n", t, p);
    int i=1,j=1;
    printf("匹配起始位置(0基):");
    int found=0;
    while(i<=n){
        if(j==0 || t[i-1]==p[j-1]){ i++; j++; }
        if(j>m){ printf(" %d", i-m-1); found=1; j=next[j]; }
        else if(i<=n && t[i-1]!=p[j-1]){
            if(j>0) j=next[j]; else i++;
        }
    }
    if(!found) printf(" 无");
    printf("\n");
    return 0;
}
